/** Generated by scaffold-crud-pages. Query hooks for Nudges.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchNudgesList,
  fetchNudgesById,
  createNudges,
  updateNudges,
  deleteNudges,
  type FetchNudgesListParams,
} from '~/services/httpServices/nudgesService';
import type { CreateNudgesRequest, UpdateNudgesRequest } from '~/types/nudges';

const DOMAIN = 'nudges';

export function useNudgesList(params?: FetchNudgesListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchNudgesList(params),
  });
}

export function useNudges(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchNudgesById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateNudges() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateNudgesRequest) => createNudges(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateNudges() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateNudgesRequest }) =>
      updateNudges(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteNudges() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteNudges(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
